#include <bits/stdc++.h>
using namespace std;

static string in;
static size_t p = 0;
static void readAll() {
    char b[1 << 16];
    size_t k;
    while ((k = fread(b, 1, sizeof b, stdin)) > 0) in.append(b, k);
}
static bool skipSpace() {
    while (p < in.size() && (unsigned char)in[p] <= ' ') p++;
    return p < in.size();
}
static string token() {
    skipSpace();
    size_t s = p;
    while (p < in.size() && (unsigned char)in[p] > ' ') p++;
    return in.substr(s, p - s);
}
static long long num() {
    skipSpace();
    bool neg = false;
    if (p < in.size() && (in[p] == '-' || in[p] == '+')) neg = in[p++] == '-';
    long long v = 0;
    while (p < in.size() && in[p] >= '0' && in[p] <= '9') v = v * 10 + (in[p++] - '0');
    return neg ? -v : v;
}

// Parses one JSON string literal starting at p into Unicode code points.
static vector<int> jsonString() {
    skipSpace();
    vector<int> s;
    p++;  // opening quote
    auto hex4 = [&]() {
        int v = stoi(in.substr(p, 4), nullptr, 16);
        p += 4;
        return v;
    };
    while (in[p] != '"') {
        unsigned char c = in[p];
        if (c == '\\') {
            char e = in[p + 1];
            p += 2;
            if (e == 'u') {
                int v = hex4();
                if (v >= 0xD800 && v < 0xDC00 && in[p] == '\\' && in[p + 1] == 'u') {
                    p += 2;
                    int lo = hex4();
                    v = 0x10000 + ((v - 0xD800) << 10) + (lo - 0xDC00);
                }
                s.push_back(v);
            } else {
                s.push_back(e == 'n' ? '\n' : e == 't' ? '\t' : e == 'r' ? '\r' : e == 'b' ? '\b' : e == 'f' ? '\f' : e);
            }
        } else {
            // Raw UTF-8 sequence.
            int len = c < 0x80 ? 1 : c < 0xE0 ? 2 : c < 0xF0 ? 3 : 4;
            int v = len == 1 ? c : c & (0x3F >> (len - 1));
            for (int k = 1; k < len; k++) v = (v << 6) | (in[p + k] & 0x3F);
            s.push_back(v);
            p += len;
        }
    }
    p++;  // closing quote
    return s;
}

// Parses a JSON array of strings starting at p.
static vector<vector<int>> jsonStrings() {
    vector<vector<int>> list;
    skipSpace();
    p++;  // [
    while (true) {
        skipSpace();
        if (in[p] == ']') break;
        if (in[p] == ',') { p++; continue; }
        list.push_back(jsonString());
    }
    p++;  // ]
    return list;
}

static bool contains(const vector<int>& line, const vector<int>& word, const vector<int>& pi) {
    size_t matched = 0;
    for (int ch : line) {
        while (matched && ch != word[matched]) matched = pi[matched - 1];
        if (ch == word[matched]) matched++;
        if (matched == word.size()) return true;
    }
    return false;
}

int main() {
    readAll();
    skipSpace();
    p++;  // outer [
    vector<vector<int>> rows = jsonStrings();
    skipSpace();
    p++;  // ,
    vector<vector<int>> words = jsonStrings();
    // Every search line: rows, columns, and both reversed.
    vector<vector<int>> lines = rows;
    for (size_t j = 0; j < rows[0].size(); j++) {
        vector<int> col;
        for (auto& row : rows) col.push_back(row[j]);
        lines.push_back(col);
    }
    for (size_t i = 0, k = lines.size(); i < k; i++) lines.emplace_back(lines[i].rbegin(), lines[i].rend());
    map<vector<int>, bool> cache;
    string out;
    for (auto& word : words) {
        auto it = cache.find(word);
        if (it == cache.end()) {
            // KMP prefix function of the word.
            vector<int> pi(word.size(), 0);
            for (size_t i = 1; i < word.size(); i++) {
                int k = pi[i - 1];
                while (k && word[i] != word[k]) k = pi[k - 1];
                if (word[i] == word[k]) k++;
                pi[i] = k;
            }
            bool found = false;
            for (auto& line : lines)
                if (contains(line, word, pi)) { found = true; break; }
            it = cache.emplace(word, found).first;
        }
        if (!out.empty()) out += ' ';
        out += it->second ? "Yes" : "No";
    }
    out += '\n';
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;

public class Main {
    static String text;
    static int at = 0;

    static void skip() {
        while (at < text.length() && Character.isWhitespace(text.charAt(at))) at++;
    }

    // Parses one JSON string literal starting at `at`.
    static String jsonString() {
        skip();
        at++;  // opening quote
        StringBuilder sb = new StringBuilder();
        while (text.charAt(at) != '"') {
            char c = text.charAt(at++);
            if (c != '\\') {
                sb.append(c);
                continue;
            }
            char e = text.charAt(at++);
            switch (e) {
                case 'n' -> sb.append('\n');
                case 't' -> sb.append('\t');
                case 'r' -> sb.append('\r');
                case 'b' -> sb.append('\b');
                case 'f' -> sb.append('\f');
                case 'u' -> {
                    sb.append((char) Integer.parseInt(text.substring(at, at + 4), 16));
                    at += 4;
                }
                default -> sb.append(e);
            }
        }
        at++;  // closing quote
        return sb.toString();
    }

    // Parses a JSON array of strings starting at `at`.
    static List<String> jsonStrings() {
        List<String> list = new ArrayList<>();
        skip();
        at++;  // [
        while (true) {
            skip();
            char c = text.charAt(at);
            if (c == ']') break;
            if (c == ',') {
                at++;
                continue;
            }
            list.add(jsonString());
        }
        at++;  // ]
        return list;
    }

    static boolean contains(int[] line, int[] word, int[] pi) {
        int matched = 0;
        for (int ch : line) {
            while (matched > 0 && ch != word[matched]) matched = pi[matched - 1];
            if (ch == word[matched]) matched++;
            if (matched == word.length) return true;
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        text = new String(System.in.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8);
        skip();
        at++;  // outer [
        List<String> rowText = jsonStrings();
        skip();
        at++;  // ,
        List<String> words = jsonStrings();
        // Work on code points; every search line is a row, a column, or one of them reversed.
        List<int[]> lines = new ArrayList<>();
        for (String r : rowText) lines.add(r.codePoints().toArray());
        int rows = lines.size(), cols = lines.get(0).length;
        for (int j = 0; j < cols; j++) {
            int[] col = new int[rows];
            for (int i = 0; i < rows; i++) col[i] = lines.get(i)[j];
            lines.add(col);
        }
        for (int i = 0, k = lines.size(); i < k; i++) {
            int[] line = lines.get(i), rev = new int[line.length];
            for (int t = 0; t < line.length; t++) rev[t] = line[line.length - 1 - t];
            lines.add(rev);
        }
        HashMap<String, Boolean> cache = new HashMap<>();
        StringBuilder out = new StringBuilder();
        for (String w : words) {
            Boolean found = cache.get(w);
            if (found == null) {
                int[] word = w.codePoints().toArray();
                // KMP prefix function of the word.
                int[] pi = new int[word.length];
                for (int i = 1; i < word.length; i++) {
                    int k = pi[i - 1];
                    while (k > 0 && word[i] != word[k]) k = pi[k - 1];
                    if (word[i] == word[k]) k++;
                    pi[i] = k;
                }
                found = false;
                for (int[] line : lines)
                    if (contains(line, word, pi)) {
                        found = true;
                        break;
                    }
                cache.put(w, found);
            }
            if (out.length() > 0) out.append(' ');
            out.append(found ? "Yes" : "No");
        }
        System.out.println(out);
    }
}

package main

import (
	"encoding/json"
	"io"
	"os"
	"slices"
)

func contains(line, word []rune, pi []int) bool {
	matched := 0
	for _, ch := range line {
		for matched > 0 && ch != word[matched] {
			matched = pi[matched-1]
		}
		if ch == word[matched] {
			matched++
		}
		if matched == len(word) {
			return true
		}
	}
	return false
}

func main() {
	raw, _ := io.ReadAll(os.Stdin)
	var input [][]string // [gridRows, words]
	json.Unmarshal(raw, &input)
	rows, words := input[0], input[1]
	// Work on code points; every search line is a row, a column, or one of them reversed.
	lines := [][]rune{}
	for _, r := range rows {
		lines = append(lines, []rune(r))
	}
	for j := range lines[0] {
		col := make([]rune, len(rows))
		for i := range rows {
			col[i] = lines[i][j]
		}
		lines = append(lines, col)
	}
	for _, line := range lines[:len(lines)] {
		rev := slices.Clone(line)
		slices.Reverse(rev)
		lines = append(lines, rev)
	}
	cache := map[string]bool{}
	out := []byte{}
	for _, w := range words {
		found, ok := cache[w]
		if !ok {
			word := []rune(w)
			// KMP prefix function of the word.
			pi := make([]int, len(word))
			for i := 1; i < len(word); i++ {
				k := pi[i-1]
				for k > 0 && word[i] != word[k] {
					k = pi[k-1]
				}
				if word[i] == word[k] {
					k++
				}
				pi[i] = k
			}
			for _, line := range lines {
				if contains(line, word, pi) {
					found = true
					break
				}
			}
			cache[w] = found
		}
		if len(out) > 0 {
			out = append(out, ' ')
		}
		if found {
			out = append(out, "Yes"...)
		} else {
			out = append(out, "No"...)
		}
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
